36.         <label>Insurance Provider</label>
37.         <InputSelect @bind-Value="model.InsuranceProvider">
38.             <option value="">-- Select --</option>
39.             <option value="Aetna">Aetna</option>
40.             <option value="BlueCross">BlueCross</option>
41.             <option value="Cigna">Cigna</option>
42.             <option value="UnitedHealth">UnitedHealth</option>
43.             <option value="None">None</option>
44.         </InputSelect>
45.         <ValidationMessage For="() => model.InsuranceProvider" />
46.     </div>
47. 
48.     @if (!showStep2)
49.     {
50.         <button type="button" @onclick="GoToStep2">Next</button>
51.     }
52. 
53.     @if (showStep2)
54.     {
55.         <h2>Appointment Details</h2>
56. 
57.         <div>
58.             <label>Preferred Doctor</label>
59.             <InputSelect @bind-Value="model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
60.                 <option value="">-- Select --</option>
61.                 @foreach (var doc in doctors)
62.                 {
63.                     <option value="@doc">@doc</option>
64.                 }
65.             </InputSelect>
66.             <ValidationMessage For="() => model.Doctor" />
67.         </div>
68. 
69.         <div>
70.             <label>Date</label>
71.             <InputDate @bind-Value="model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
72.             <ValidationMessage For="() => model.AppointmentDate" />
73.         </div>
74. 
75.         <div>
76.             <label>Time Slot</label>
77.             <InputSelect @bind-Value="model.TimeSlot">
78.                 <option value="">-- Select --</option>
79.                 @foreach (var slot in availableSlots)
80.                 {
81.                     <option value="@slot">@slot</option>
82.                 }
83.             </InputSelect>
84.             <ValidationMessage For="() => model.TimeSlot" />
85.         </div>
86. 
87.         <div>
88.             <label>Reason for Visit</label>
89.             <InputTextArea @bind-Value="model.ReasonForVisit" />
90.             <ValidationMessage For="() => model.ReasonForVisit" />
91.         </div>
92. 
93.         <button type="button" @onclick="GoToStep1">Back</button>
94.         <button type="button" @onclick="CheckAvailability" disabled="@isSubmitting">
95.             @(isSubmitting ? "Checking..." : "Check Availability")
96.         </button>
97.     }
98. 
