110. @code {
111.     private EditContext editContext = default!;
112.     private AppointmentModel model = new();
113.     private CustomValidator? customValidator;
114. 
115.     private bool showStep2;
116.     private bool isSubmitting;
117.     private bool isConfirmed;
118.     private bool bookingComplete;
119. 
120.     private List<string> doctors = new();
121.     private List<string> availableSlots = new();
122. 
123.     private static readonly string[] Step1Fields = { "PatientName", "Email", "Phone", "InsuranceProvider" };
124. 
125.     protected override async Task OnInitializedAsync()
126.     {
127.         editContext = new EditContext(model);
128.         doctors = await AppointmentService.GetDoctorsAsync();
129.     }
130. 
131.     private void GoToStep1()
132.     {
133.         showStep2 = false;
134.         isConfirmed = false;
135.     }
136. 
137.     private void GoToStep2()
138.     {
139.         editContext.Validate();
140. 
141.         var hasStep1Errors = Step1Fields.Any(f =>
142.             editContext.GetValidationMessages(editContext.Field(f)).Any());
143. 
144.         if (!hasStep1Errors)
145.         {
146.             showStep2 = true;
147.         }
148.     }
149. 
150.     private async Task OnDoctorOrDateChanged()
151.     {
152.         model.TimeSlot = null;
153.         if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
154.         {
155.             availableSlots = await AppointmentService.GetAvailableSlotsAsync(
156.                 model.Doctor, model.AppointmentDate.Value);
157.         }
158.         else
159.         {
160.             availableSlots = new();
161.         }
162.     }
163. 
164.     private async Task CheckAvailability()
165.     {
166.         customValidator?.ClearErrors();
167.         editContext.Validate();
168. 
169.         var hasErrors = editContext.GetValidationMessages().Any();
170.         if (hasErrors) return;
171. 
172.         // Validate future date
173.         if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
174.         {
175.             customValidator!.DisplayErrors(new Dictionary<string, List<string>>
176.             {
177.                 ["AppointmentDate"] = new() { "Appointment date must be in the future." }
178.             });
179.             return;
180.         }
181. 
182.         isSubmitting = true;
183.         try
184.         {
185.             var errors = await AppointmentService.ValidatePatientAsync(
186.                 model.Email!, model.InsuranceProvider!, model.Doctor!, model.TimeSlot!);
187. 
188.             if (errors.Count > 0)
189.             {
190.                 customValidator!.DisplayErrors(errors);
191.                 isConfirmed = false;
192.             }
193.             else
194.             {
195.                 isConfirmed = true;
196.             }
197.         }
198.         finally
199.         {
200.             isSubmitting = false;
201.         }
202.     }
203. 
204.     private void HandleSubmit()
205.     {
206.         bookingComplete = true;
207.     }
208. 
209.     public class AppointmentModel
210.     {
211.         [Required(ErrorMessage = "Patient name is required.")]
212.         public string? PatientName { get; set; }
213. 
214.         [Required(ErrorMessage = "Email is required.")]
215.         [EmailAddress(ErrorMessage = "Invalid email format.")]
216.         public string? Email { get; set; }
217. 
218.         [Required(ErrorMessage = "Phone number is required.")]
219.         [Phone(ErrorMessage = "Invalid phone number format.")]
220.         public string? Phone { get; set; }
221. 
222.         [Required(ErrorMessage = "Insurance provider is required.")]
223.         public string? InsuranceProvider { get; set; }
224. 
225.         [Required(ErrorMessage = "Please select a doctor.")]
226.         public string? Doctor { get; set; }
227. 
228.         [Required(ErrorMessage = "Appointment date is required.")]
229.         public DateOnly? AppointmentDate { get; set; }
230. 
231.         [Required(ErrorMessage = "Please select a time slot.")]
232.         public string? TimeSlot { get; set; }
233. 
234.         [Required(ErrorMessage = "Reason for visit is required.")]
235.         [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
236.         public string? ReasonForVisit { get; set; }
237.     }
238. }
